import json
import os
from typing import Iterator, Optional, Union
import boto3
from botocore.exceptions import NoCredentialsError, ClientError

class InputReader:
    def __init__(self, source: Union[str, bytes], fail_on_missing: bool = False):
        self.source = source
        self.fail_on_missing = fail_on_missing
        self.is_bucket = self._is_s3_bucket()

    def _is_s3_bucket(self) -> bool:
        return self.source.startswith("s3://")

    def _get_s3_client(self):
        return boto3.client('s3')

    def _get_bucket_and_key(self):
        if not self.is_bucket:
            raise ValueError("Source is not an S3 bucket path.")
        parts = self.source[5:].split('/', 1)
        if len(parts) != 2:
            raise ValueError("Invalid S3 bucket path.")
        return parts[0], parts[1]

    def _read_from_file(self) -> Iterator[str]:
        if not os.path.exists(self.source):
            if self.fail_on_missing:
                raise FileNotFoundError(f"File {self.source} not found.")
            else:
                return iter([])

        with open(self.source, 'r') as file:
            for line in file:
                yield line

    def _read_from_bucket(self) -> Iterator[str]:
        bucket, key = self._get_bucket_and_key()
        s3_client = self._get_s3_client()

        try:
            response = s3_client.get_object(Bucket=bucket, Key=key)
            for line in response['Body'].iter_lines():
                yield line.decode('utf-8')
        except (NoCredentialsError, ClientError) as e:
            if self.fail_on_missing:
                raise FileNotFoundError(f"Could not read from S3 bucket: {e}")
            else:
                return iter([])

    def __iter__(self) -> Iterator[str]:
        if self.is_bucket:
            return self._read_from_bucket()
        else:
            return self._read_from_file()

    @classmethod
    def from_json(cls, json_str: str) -> 'InputReader':
        data = json.loads(json_str)
        return cls(source=data['source'], fail_on_missing=data.get('fail_on_missing', False))

    def to_json(self) -> str:
        return json.dumps({
            'source': self.source,
            'fail_on_missing': self.fail_on_missing
        })
